mapper.select:
select s.id,s.name,s.code,s.admin_user_id,s.admin_phone,s.liaison,s.phone,s.area,s.address,s.remark,s.category,
s.risk_level,s.supplier_tenant,s.tenant,s.deleted,s.create_by,s.creator_id,s.creator_type,s.create_time,s.update_by,s.updater_id,s.updater_type,s.update_time
from supplier s
left join supplier_authentication sa
on s.id = sa.supplier_id


        and s.id in

            #{id}



        and s.name like concat("%",#{param.keyword},"%")


        and sa.status = #{param.status}


        and sa.type = #{param.type}

    and sa.status != "INVALID"
    and s.tenant = #{param.tenant}

SELECT s.admin_user_id AS id ,s.admin_user_name as name FROM supplier s LEFT JOIN supplier_authentication sa ON s.id = sa.supplier_id
and s.admin_user_name like concat("%",#{param.keyword},"%")
and sa.STATUS = 'CERTIFIED' and s.tenant = ${param.tenant}
UNION SELECT p.user_id AS id,p.user_name as name FROM purchaser p LEFT JOIN purchaser_authentication pa ON p.id = pa.purchaser_id
and p.user_name like concat("%",#{param.keyword},"%")
and pa.`status` = 'CERTIFIED' and p.tenant = ${param.tenant};
